package main

import (
	"bufio"
	"crypto/tls"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"net/http"
	neturl "net/url"
	"os"
	"sort"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

const version = "dev"

const usageText = `Transform JSON (from a file, URL, or stdin) into discrete assignments to make it greppable

Usage:
  gron [OPTIONS] [FILE|URL|-]

Options:
  -u, --ungron     Reverse the operation (turn assignments back into JSON)
  -v, --values     Print just the values of provided assignments
  -c, --colorize   Colorize output (default on tty)
  -m, --monochrome Monochrome (don't colorize output)
  -s, --stream     Treat each line of input as a separate JSON object
  -k, --insecure   Disable certificate validation
  -x, --proxy      Set proxy configuration
      --noproxy    Comma-separated list of hosts for which not to use a proxy, if one is specified.
  -j, --json       Represent gron data as JSON stream
      --no-sort    Don't sort output (faster)
      --version    Print version information

Exit Codes:
  0	OK
  1	Failed to open file
  2	Failed to read input
  3	Failed to form statements
  4	Failed to fetch URL
  5	Failed to parse statements
  6	Failed to encode JSON

Examples:
  gron /tmp/apiresponse.json
  gron http://jsonplaceholder.typicode.com/users/1 
  curl -s http://jsonplaceholder.typicode.com/users/1 | gron
  gron http://jsonplaceholder.typicode.com/users/1 | grep company | gron --ungron
`

type options struct {
	ungron     bool
	values     bool
	colorize   bool
	monochrome bool
	stream     bool
	insecure   bool
	json       bool
	noSort     bool
	version    bool
	proxy      string
	noProxy    string
}

type pathPart struct {
	isIndex bool
	key     string
	index   int
}

type statement struct {
	root     string
	path     []pathPart
	rawValue string
	value    any
}

var (
	errNoStatement      = errors.New("no statement")
	errStatementNoValue = errors.New("statement has no value")
	errInvalidStatement = errors.New("invalid statement")
)

func main() {
	os.Exit(run(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
}

func run(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
	opts, positional, code, ok := parseFlags(args, stdout, stderr)
	if !ok {
		return code
	}

	inputArg := ""
	if len(positional) > 0 {
		inputArg = positional[0]
	}

	input, code, err := openInput(inputArg, stdin, opts)
	if err != nil {
		fmt.Fprintln(stderr, err)
		return code
	}
	defer input.Close()

	switch {
	case opts.ungron:
		return runUngron(input, stdout, stderr, opts)
	case opts.values:
		return runValues(input, stdout, stderr)
	default:
		return runGron(input, stdout, stderr, opts)
	}
}

func parseFlags(args []string, stdout, stderr io.Writer) (options, []string, int, bool) {
	var opts options

	fs := flag.NewFlagSet("gron", flag.ContinueOnError)
	fs.SetOutput(io.Discard)

	fs.BoolVar(&opts.ungron, "u", false, "")
	fs.BoolVar(&opts.ungron, "ungron", false, "")
	fs.BoolVar(&opts.values, "v", false, "")
	fs.BoolVar(&opts.values, "values", false, "")
	fs.BoolVar(&opts.colorize, "c", false, "")
	fs.BoolVar(&opts.colorize, "colorize", false, "")
	fs.BoolVar(&opts.monochrome, "m", false, "")
	fs.BoolVar(&opts.monochrome, "monochrome", false, "")
	fs.BoolVar(&opts.stream, "s", false, "")
	fs.BoolVar(&opts.stream, "stream", false, "")
	fs.BoolVar(&opts.insecure, "k", false, "")
	fs.BoolVar(&opts.insecure, "insecure", false, "")
	fs.StringVar(&opts.proxy, "x", "", "")
	fs.StringVar(&opts.proxy, "proxy", "", "")
	fs.StringVar(&opts.noProxy, "noproxy", "", "")
	fs.BoolVar(&opts.json, "j", false, "")
	fs.BoolVar(&opts.json, "json", false, "")
	fs.BoolVar(&opts.noSort, "no-sort", false, "")
	fs.BoolVar(&opts.version, "version", false, "")

	if err := fs.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			printUsage(stdout)
			return options{}, nil, 0, false
		}
		fmt.Fprintln(stderr, err)
		printUsage(stderr)
		return options{}, nil, 2, false
	}

	if opts.version {
		fmt.Fprintf(stdout, "gron version %s\n", version)
		return options{}, nil, 0, false
	}

	return opts, fs.Args(), 0, true
}

func printUsage(w io.Writer) {
	fmt.Fprint(w, usageText)
}

func openInput(arg string, stdin io.Reader, opts options) (io.ReadCloser, int, error) {
	if arg == "" || arg == "-" {
		return io.NopCloser(stdin), 0, nil
	}

	if isURL(arg) {
		body, err := fetchURL(arg, opts)
		if err != nil {
			return nil, 4, err
		}
		return body, 0, nil
	}

	file, err := os.Open(arg)
	if err != nil {
		return nil, 1, err
	}
	return file, 0, nil
}

func isURL(arg string) bool {
	return strings.HasPrefix(arg, "http://") || strings.HasPrefix(arg, "https://")
}

func fetchURL(raw string, opts options) (io.ReadCloser, error) {
	transport := &http.Transport{}
	if opts.insecure {
		transport.TLSClientConfig = &tls.Config{InsecureSkipVerify: true}
	}
	transport.Proxy = proxyFunc(opts)

	client := &http.Client{Transport: transport}
	req, err := http.NewRequest(http.MethodGet, raw, nil)
	if err != nil {
		return nil, err
	}

	req.Header.Set("Accept", "application/json")
	req.Header.Set("User-Agent", "gron/"+version)

	resp, err := client.Do(req)
	if err != nil {
		return nil, err
	}
	return resp.Body, nil
}

func proxyFunc(opts options) func(*http.Request) (*neturl.URL, error) {
	if opts.proxy == "" {
		return http.ProxyFromEnvironment
	}

	proxyURL, err := neturl.Parse(opts.proxy)
	if err != nil {
		return func(*http.Request) (*neturl.URL, error) {
			return nil, err
		}
	}

	noProxy := parseNoProxy(opts.noProxy)

	return func(req *http.Request) (*neturl.URL, error) {
		if shouldBypassProxy(req.URL, noProxy) {
			return nil, nil
		}
		return proxyURL, nil
	}
}

func parseNoProxy(raw string) []string {
	if raw == "" {
		return nil
	}
	parts := strings.Split(raw, ",")
	out := make([]string, 0, len(parts))
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part != "" {
			out = append(out, part)
		}
	}
	return out
}

func shouldBypassProxy(u *neturl.URL, noProxy []string) bool {
	if len(noProxy) == 0 {
		return false
	}

	host := u.Hostname()
	hostPort := u.Host

	for _, entry := range noProxy {
		switch {
		case entry == "*":
			return true
		case strings.EqualFold(host, entry), strings.EqualFold(hostPort, entry):
			return true
		case strings.HasPrefix(entry, ".") && strings.HasSuffix(host, entry):
			return true
		case strings.HasSuffix(host, "."+entry):
			return true
		}
	}

	return false
}

func runGron(input io.Reader, stdout, stderr io.Writer, opts options) int {
	out := bufio.NewWriter(stdout)
	defer out.Flush()

	if opts.stream {
		if err := emitNode(out, nil, []any{}, opts); err != nil {
			out.Flush()
			fmt.Fprintf(stderr, "failed to encode JSON: %v\n", err)
			return 6
		}

		scanner := newScanner(input)
		index := 0
		for scanner.Scan() {
			value, err := decodeJSON(strings.NewReader(scanner.Text()))
			if err != nil {
				out.Flush()
				fmt.Fprintf(stderr, "failed to form statements: %v\n", err)
				return 3
			}

			if err := emitNode(out, []pathPart{{isIndex: true, index: index}}, value, opts); err != nil {
				out.Flush()
				fmt.Fprintf(stderr, "failed to encode JSON: %v\n", err)
				return 6
			}
			index++
		}

		if err := scanner.Err(); err != nil {
			out.Flush()
			fmt.Fprintln(stderr, err)
			return 2
		}

		return 0
	}

	value, err := decodeJSON(input)
	if err != nil {
		fmt.Fprintf(stderr, "failed to form statements: %v\n", err)
		return 3
	}

	if err := emitNode(out, nil, value, opts); err != nil {
		out.Flush()
		fmt.Fprintf(stderr, "failed to encode JSON: %v\n", err)
		return 6
	}

	return 0
}

func runUngron(input io.Reader, stdout, stderr io.Writer, opts options) int {
	var (
		merged any
		seen   bool
	)

	if opts.json {
		scanner := newScanner(input)
		for scanner.Scan() {
			line := scanner.Text()
			record, err := decodeJSON(strings.NewReader(line))
			if err != nil {
				fmt.Fprintln(stderr, err)
				return 5
			}

			stmtText, err := jsonLayoutToStatement(record)
			if err != nil {
				fmt.Fprintln(stderr, err)
				return 5
			}

			stmt, err := parseUngronStatement(stmtText)
			if err != nil {
				fmt.Fprintf(stderr, "ungron failed for `%s`: %v\n", stmtText, err)
				return 5
			}

			tree := buildTree(stmt)
			merged, err = mergeValues(merged, tree)
			if err != nil {
				fmt.Fprintf(stderr, "failed to merge statements: %v\n", err)
				return 5
			}
			seen = true
		}

		if err := scanner.Err(); err != nil {
			fmt.Fprintln(stderr, err)
			return 2
		}

		if !seen {
			fmt.Fprintln(stderr, "no statements were parsed")
			return 5
		}

		return writeIndentedJSON(stdout, unwrapJSONRoot(merged), stderr)
	}

	scanner := newScanner(input)
	for scanner.Scan() {
		line := scanner.Text()
		if strings.TrimSpace(line) == "" {
			continue
		}

		if !looksLikeUngronStatement(line) {
			continue
		}

		stmt, err := parseUngronStatement(line)
		if err != nil {
			if errors.Is(err, errNoStatement) {
				continue
			}
			fmt.Fprintf(stderr, "ungron failed for `%s`: %v\n", line, err)
			return 5
		}

		tree := buildTree(stmt)
		merged, err = mergeValues(merged, tree)
		if err != nil {
			fmt.Fprintf(stderr, "failed to merge statements: %v\n", err)
			return 5
		}
		seen = true
	}

	if err := scanner.Err(); err != nil {
		fmt.Fprintln(stderr, err)
		return 2
	}

	if !seen {
		fmt.Fprintln(stderr, "no statements were parsed")
		return 5
	}

	return writeIndentedJSON(stdout, unwrapJSONRoot(merged), stderr)
}

func writeIndentedJSON(stdout io.Writer, value any, stderr io.Writer) int {
	enc := json.NewEncoder(stdout)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	if err := enc.Encode(value); err != nil {
		fmt.Fprintf(stderr, "failed to encode JSON: %v\n", err)
		return 6
	}
	return 0
}

func runValues(input io.Reader, stdout, stderr io.Writer) int {
	scanner := newScanner(input)
	out := bufio.NewWriter(stdout)
	defer out.Flush()

	for scanner.Scan() {
		line := scanner.Text()
		if line == "" {
			out.Flush()
			fmt.Fprintf(stderr, "failed to parse '%s' as gron statement\n", line)
			return 5
		}

		if !strings.Contains(line, "=") {
			continue
		}

		stmt, err := parseValueStatement(line)
		if err != nil {
			out.Flush()
			fmt.Fprintf(stderr, "failed to parse '%s' as gron statement\n", line)
			return 5
		}

		if err := writeValue(out, stmt.rawValue); err != nil {
			out.Flush()
			fmt.Fprintln(stderr, err)
			return 2
		}
	}

	if err := scanner.Err(); err != nil {
		out.Flush()
		fmt.Fprintln(stderr, err)
		return 2
	}

	return 0
}

func newScanner(r io.Reader) *bufio.Scanner {
	scanner := bufio.NewScanner(r)
	scanner.Buffer(make([]byte, 1024), 10*1024*1024)
	return scanner
}

func decodeJSON(r io.Reader) (any, error) {
	var value any
	dec := json.NewDecoder(r)
	dec.UseNumber()
	if err := dec.Decode(&value); err != nil {
		return nil, err
	}
	return value, nil
}

func emitNode(w io.Writer, path []pathPart, value any, opts options) error {
	printed := value
	switch value.(type) {
	case map[string]any:
		printed = map[string]any{}
	case []any:
		printed = []any{}
	}

	if opts.json {
		if err := emitJSONStreamLine(w, path, printed); err != nil {
			return err
		}
	} else {
		if err := emitStatementLine(w, path, printed); err != nil {
			return err
		}
	}

	switch node := value.(type) {
	case map[string]any:
		if opts.noSort {
			for key, child := range node {
				if err := emitNode(w, appendPath(path, pathPart{key: key}), child, opts); err != nil {
					return err
				}
			}
			return nil
		}

		keys := make([]string, 0, len(node))

		for key := range node {
			keys = append(keys, key)
		}
		sort.Strings(keys)
		for _, key := range keys {
			if err := emitNode(w, appendPath(path, pathPart{key: key}), node[key], opts); err != nil {
				return err
			}
		}
	case []any:
		for index, child := range node {
			if err := emitNode(w, appendPath(path, pathPart{isIndex: true, index: index}), child, opts); err != nil {
				return err
			}
		}
	}

	return nil
}

func appendPath(path []pathPart, part pathPart) []pathPart {
	next := make([]pathPart, len(path)+1)
	copy(next, path)
	next[len(path)] = part
	return next
}

func emitStatementLine(w io.Writer, path []pathPart, value any) error {
	encoded, err := encodeCompact(value)
	if err != nil {
		return err
	}
	_, err = fmt.Fprintf(w, "%s = %s;\n", formatPath(path), encoded)
	return err
}

func emitJSONStreamLine(w io.Writer, path []pathPart, value any) error {
	record := []any{pathToJSONArray(path), value}
	encoded, err := encodeCompact(record)
	if err != nil {
		return err
	}
	_, err = fmt.Fprintln(w, encoded)
	return err
}

func encodeCompact(value any) (string, error) {
	var buf strings.Builder
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	if err := enc.Encode(value); err != nil {
		return "", err
	}
	return strings.TrimSuffix(buf.String(), "\n"), nil
}

func pathToJSONArray(path []pathPart) []any {
	out := make([]any, 0, len(path))
	for _, part := range path {
		if part.isIndex {
			out = append(out, part.index)
		} else {
			out = append(out, part.key)
		}
	}
	return out
}

func formatPath(path []pathPart) string {
	var buf strings.Builder
	buf.WriteString("json")
	for _, part := range path {
		if part.isIndex {
			fmt.Fprintf(&buf, "[%d]", part.index)
			continue
		}
		if isJSIdentifier(part.key) {
			buf.WriteByte('.')
			buf.WriteString(part.key)
			continue
		}
		encoded, _ := encodeCompact(part.key)
		buf.WriteByte('[')
		buf.WriteString(encoded)
		buf.WriteByte(']')
	}
	return buf.String()
}

func isJSIdentifier(s string) bool {
	if s == "" || reservedWords[s] {
		return false
	}

	i := 0
	r, size := utf8.DecodeRuneInString(s)
	if !isIdentifierStart(r) {
		return false
	}
	i += size

	for i < len(s) {
		r, size = utf8.DecodeRuneInString(s[i:])
		if !isIdentifierPart(r) {
			return false
		}
		i += size
	}

	return true
}

func looksLikeUngronStatement(line string) bool {
	if line == "" {
		return false
	}
	r, _ := utf8.DecodeRuneInString(line)
	if !isIdentifierStart(r) {
		return false
	}
	return strings.ContainsAny(line, "=[.")
}

func parseUngronStatement(line string) (statement, error) {
	stmt, err := parseStatementLine(line, true)
	if err != nil {
		return statement{}, err
	}

	value, err := decodeStatementValue(stmt.rawValue)
	if err != nil {
		return statement{}, err
	}
	stmt.value = value
	return stmt, nil
}

func parseValueStatement(line string) (statement, error) {
	return parseStatementLine(line, false)
}

func parseStatementLine(line string, requireSemicolon bool) (statement, error) {
	root, index := parseIdentifier(line, 0)
	if root == "" {
		return statement{}, errNoStatement
	}

	stmt := statement{root: root}
	index = skipSpaces(line, index)

	for index < len(line) {
		switch line[index] {
		case '.':
			key, next := parseIdentifier(line, index+1)
			if key == "" {
				return statement{}, errInvalidStatement
			}
			stmt.path = append(stmt.path, pathPart{key: key})
			index = skipSpaces(line, next)
		case '[':
			part, next, err := parseBracketPart(line, index)
			if err != nil {
				return statement{}, err
			}
			stmt.path = append(stmt.path, part)
			index = skipSpaces(line, next)
		case '=':
			raw, err := extractValue(line, index+1, requireSemicolon)
			if err != nil {
				return statement{}, err
			}
			stmt.rawValue = raw
			return stmt, nil
		default:
			if unicode.IsSpace(rune(line[index])) {
				index = skipSpaces(line, index)
				if index < len(line) && line[index] == '=' {
					continue
				}
				if len(stmt.path) == 0 && index >= len(line) {
					return statement{}, errNoStatement
				}
				return statement{}, errStatementNoValue
			}
			if len(stmt.path) == 0 {
				return statement{}, errNoStatement
			}
			return statement{}, errStatementNoValue
		}
	}

	if len(stmt.path) == 0 {
		return statement{}, errNoStatement
	}
	return statement{}, errStatementNoValue
}

func parseIdentifier(s string, start int) (string, int) {
	if start >= len(s) {
		return "", start
	}

	r, size := utf8.DecodeRuneInString(s[start:])
	if !isIdentifierStart(r) {
		return "", start
	}

	index := start + size
	for index < len(s) {
		r, size = utf8.DecodeRuneInString(s[index:])
		if !isIdentifierPart(r) {
			break
		}
		index += size
	}

	return s[start:index], index
}

func skipSpaces(s string, start int) int {
	index := start
	for index < len(s) {
		if !unicode.IsSpace(rune(s[index])) {
			break
		}
		index++
	}
	return index
}

func isIdentifierStart(r rune) bool {
	return r == '$' || r == '_' || unicode.IsLetter(r)
}

func isIdentifierPart(r rune) bool {
	return isIdentifierStart(r) || unicode.IsDigit(r)
}

func parseBracketPart(line string, start int) (pathPart, int, error) {
	index := start + 1
	if index >= len(line) {
		return pathPart{}, 0, errInvalidStatement
	}

	if line[index] == '"' {
		value, next, err := parseJSONStringToken(line, index)
		if err != nil {
			return pathPart{}, 0, errInvalidStatement
		}
		if next >= len(line) || line[next] != ']' {
			return pathPart{}, 0, errInvalidStatement
		}
		return pathPart{key: value}, next + 1, nil
	}

	close := strings.IndexByte(line[index:], ']')
	if close < 0 {
		return pathPart{}, 0, errStatementNoValue
	}

	token := strings.TrimSpace(line[index : index+close])
	value, err := strconv.Atoi(token)
	if err != nil {
		return pathPart{}, 0, fmt.Errorf("invalid integer key `%s`", token)
	}

	return pathPart{isIndex: true, index: value}, index + close + 1, nil
}

func parseJSONStringToken(line string, start int) (string, int, error) {
	var value string
	dec := json.NewDecoder(strings.NewReader(line[start:]))
	if err := dec.Decode(&value); err != nil {
		return "", 0, err
	}
	return value, start + int(dec.InputOffset()), nil
}

func extractValue(line string, start int, requireSemicolon bool) (string, error) {
	value := strings.TrimSpace(line[start:])
	if requireSemicolon {
		semi := strings.IndexByte(value, ';')
		if semi < 0 {
			return "", errStatementNoValue
		}
		return strings.TrimSpace(value[:semi]), nil
	}

	if semi := strings.IndexByte(value, ';'); semi >= 0 {
		value = value[:semi]
	}
	return strings.TrimSpace(value), nil
}

func decodeStatementValue(raw string) (any, error) {
	if raw == "" {
		return nil, fmt.Errorf("invalid value `%s`", raw)
	}
	value, err := decodeJSON(strings.NewReader(raw))
	if err != nil {
		return nil, fmt.Errorf("invalid value `%s`", raw)
	}
	return value, nil
}

func buildTree(stmt statement) any {
	var node any = stmt.value
	for index := len(stmt.path) - 1; index >= 0; index-- {
		part := stmt.path[index]
		if part.isIndex {
			array := make([]any, part.index+1)
			array[part.index] = node
			node = array
			continue
		}
		node = map[string]any{part.key: node}
	}
	return map[string]any{stmt.root: node}
}

func mergeValues(existing, next any) (any, error) {
	if existing == nil {
		return next, nil
	}

	switch current := existing.(type) {
	case map[string]any:
		other, ok := next.(map[string]any)
		if !ok {
			return nil, errors.New("cannot merge object with non-object")
		}
		for key, value := range other {
			if prior, ok := current[key]; ok {
				merged, err := mergeValues(prior, value)
				if err != nil {
					return nil, err
				}
				current[key] = merged
				continue
			}
			current[key] = value
		}
		return current, nil
	case []any:
		other, ok := next.([]any)
		if !ok {
			return nil, errors.New("cannot merge array with non-array")
		}
		if len(other) > len(current) {
			expanded := make([]any, len(other))
			copy(expanded, current)
			current = expanded
		}
		for index, value := range other {
			if value == nil {
				continue
			}
			if current[index] == nil {
				current[index] = value
				continue
			}
			merged, err := mergeValues(current[index], value)
			if err != nil {
				return nil, err
			}
			current[index] = merged
		}
		return current, nil
	default:
		return next, nil
	}
}

